\label{THM:second}
At the critical inverse temperature $\beta=\beta_c$, 
\begin{align}
    \lim_{n\rightarrow\infty} \widetilde{M}_n(\beta_c)=0.
\end{align}

\label{MainTHM:first}
Under Assumption \ref{assu:uniqClus}, at the inverse temperature $\beta=\beta_c$,
\begin{align}\label{eq:mbeta}
m^*(\beta_c)=0.
\end{align}

\label{Prop:limitDxy}
Suppose that Assumption \ref{assu:uniqClus} holds. Then, at the critical inverse temperature $\beta=\beta_c,$ for any fixed sites $x$ and $y$,
\begin{align}\label{eq:limDxy}
    \lim_{L\rightarrow \infty} D_{1,x,y}(L)=\lim_{L\rightarrow \infty} D_{2,x,y}(L)=0.
\end{align}

\label{LM:highTem} When $\beta< \beta_c,$
\begin{align}
     \lim_{L\rightarrow \infty} \frac{1}{|B_n|^2}\sum_{x,y\in B_n}\Big\langle S_x \cdot S_y\Big\rangle_{L,P,\beta}\leq \frac{1}{2\beta}\frac{1}{|B_n|^2}\sum_{x,y\in B_n}G(x,y).
\end{align} Especially, $G$ is independent of $\beta$ and
\begin{align}\label{eq:LimGXY}
    \lim_{|x-y|\rightarrow \infty} G(x,y)=0.
\end{align}

For any fixed sites $x$, $y\in \mathbb{Z}^3$, $\langle S_x\cdot S_y\rangle_{L,0,\beta}$ is an increasing function in both $L$ and $\beta$ variables, and
\begin{align}\label{eq:TwoLimit}
\lim_{\beta \nearrow \beta_c}\lim_{L\rightarrow \infty}\langle S_x\cdot S_y\rangle_{L,0,\beta}=\lim_{L\rightarrow \infty}\lim_{\beta \nearrow \beta_c}\langle S_x\cdot S_y\rangle_{L,0,\beta}=\langle S_x\cdot S_y\rangle_{0,\beta_c}.
    \end{align}

\label{LM:GraWithSink}
Under Assumption \ref{assu:uniqClus}, as $L\rightarrow \infty$, almost surely, any unpaired graphs $\mathcal{G}_{\delta}(x\rightarrow y)$ and $\mathcal{G}_{0}(y\rightarrow x)$ generated by $\displaystyle\lim_{L\rightarrow \infty}\frac{\tilde{F}_{\delta,L}(x\rightarrow y)Z_{0,L}}{Z_{\delta,L}Z_{0,L}}$ and $\displaystyle\lim_{L\rightarrow \infty}\frac{F_{0,L}(y\rightarrow x)Z_{\delta,L}}{Z_{\delta,L}Z_{0,L}}$ can be decomposed into a union of finite loops $D_{\lambda}$ and a path $\mathcal{P}(x\rightarrow y)$ (or $\mathcal{Q}(y\rightarrow x)$ respectively) 
\begin{align}\label{eq:gDelta0}
\begin{split}
    \mathcal{G}_{\delta}(x\rightarrow y)=\Big(\bigcup_{\lambda\in \Upsilon_1} \mathcal{D}_{\lambda}\Big)\bigcup \mathcal{P}(x\rightarrow y);\\
    \mathcal{G}_{ 0}(y\rightarrow x)=\Big(\bigcup_{\lambda\in \Upsilon_2} \mathcal{D}_{\lambda}\Big)\bigcup \mathcal{Q}(y\rightarrow x).
\end{split}
\end{align}

For a fixed large integer $N$ so that $|x|+|y|<N$, a partially paired graph $G_{N}$ in the region $|z|\leq N$ satisfies the following properties:
    \begin{itemize}
    \item[(1)] Its underlying unpaired graph, $\Pi(G_N)$, is $\Big(\mathcal{G}_{\delta}(x\rightarrow y), \mathcal{G}_0\Big)\Big|_{|z|\leq N}$ or $\Big(\mathcal{G}_{\delta}, \mathcal{G}_0(y\rightarrow x)\Big)\Big|_{|z|\leq N}$. Recall unpaired graphs $\Big(\mathcal{G}_{\delta}(x\rightarrow y), \mathcal{G}_0\Big)$ or $\Big(\mathcal{G}_{\delta}, \mathcal{G}_0(y\rightarrow x)\Big)$ from \eqref{def:sdnn}.
    \item[(2)] In the interior, at site $z$ with $|z|<N$ and $z\not\in \{x,y\}$, every incoming edge is paired with an outgoing one; 
    \item[(3)] At the sites $x$ and $y$, the edges are not paired;
    \item[(4)] On the boundary, at site $z$ with $|z|=N$, the edges are not paired. 
    \end{itemize}
    We denote this set of graphs by $PP_{N}$, i.e.
    \begin{align}\label{def:partPair}
        PP_{N}:=\Big\{G_{N}\ \Big|\ G_{N}\ \text{is a partially paired graph in the region }\ |z|\leq N\Big\}.
    \end{align}

\label{def:repres}
For any $$G_{\delta,N}(x\rightarrow y),\ G_{0,N}(y\rightarrow x)\in PP_{N},$$ we use them to represent two sets of paired infinite graphs, specifically,
\begin{align}\label{eq:PartPaired1}
  \begin{split}
      \widetilde{G_{\delta,N}}(x\rightarrow y) :=\Big\{ F\ \Big|& \ F=F_{\delta}(x\rightarrow y) \ \text{is a paired infinite graph;}\\ & F\Big|_{|z|< N}=G_{\delta,N}(x\rightarrow y)\Big|_{|z|<N};
       \ \Pi(F)\Big|_{|z|\leq N}=\Pi\big(G_{\delta,N}(x\rightarrow y)\big) \Big\},
  \end{split}
\end{align}
and
\begin{align}\label{eq:PartPaired2}
  \begin{split}
      \widetilde{G_{0,N}}(y\rightarrow x) :=\Big\{ F\ \Big|& \ F=F_{0}(y\rightarrow x) \ \text{is a paired infinite graph;}\\ & F\Big|_{|z|< N}=G_{0,N}(y\rightarrow x)\Big|_{|z|<N};
      \ \Pi(F)\Big|_{|z|\leq N}=\Pi\big(G_{0,N}(y\rightarrow x)\big) \Big\}.
  \end{split}
\end{align}

The identities in \eqref{eq:finitelyLooped} are consistent for different $N$'s in the sense that for any $M>N$, 
    \begin{align}\label{eq:consist}
        D_{\widehat{G_{\#,N}}(x\rightarrow y) }=\sum_{
\begin{array}{cc}
        &W_{\#,M}\big|_{|z|<N}=G_{\#,N} \\ 
        &\Pi(W_{\#,M})\big|_{|z|\leq N}=\Pi(G_{\#,N}) 
\end{array}
        } D_{\widehat{W_{\#,M}}(x\rightarrow y) }.
    \end{align}

\label{prop:keyWeights}
Suppose that $P=P(x\rightarrow y)$ is a union of paired paths $x\rightarrow y$, $y\rightarrow x$, and loops $x\rightarrow x$, $y\rightarrow y$ in the region $|z|\leq N$, except that at $x$ and $y$ the edges are not paired.

Suppose that $G_{\delta,N}(x\rightarrow y)$ is a partially paired graph in the region $|z|\leq N$, and $P\subset G_{\delta,N}(x\rightarrow y) $ contains all the paired paths and loops connecting $x$ and $y$.
$G_{0,N}(y\rightarrow x)$ is the partially paired graph obtained by switching $P$ in $G_{\delta,N}(x\rightarrow y)$

Then $\widehat{G_{\delta,N}}(x\rightarrow y)$ and $\widehat{G_{0,N}}(y\rightarrow x)$ have the same weights
    \begin{align}\label{eq:equalWeights}
        D_{\widehat{G_{\delta,N}}(x\rightarrow y) }=D_{\widehat{G_{0,N}}(y\rightarrow x) }.
    \end{align}

Suppose that $G_{\delta,\mathcal{P}}=G_{\delta,\mathcal{P}}(x\rightarrow y)$ is a paired infinite graph. And $\mathcal{P}=\mathcal{P}(x\rightarrow y)$ is an unpaired subgraph in $\Pi(G_{\delta,\mathcal{P}})$.



We perform a surgical switching, using $\mathcal{P}$, on $G_{\delta,\mathcal{P}}$ to obtain $G_{0,\overline{\mathcal{P}}}=G_{0,\overline{\mathcal{P}}}(y\rightarrow x)$ as follows.


For $G_{0,\overline{\mathcal{P}}}$, its corresponding unpaired graph $\Pi(G_{0,\overline{\mathcal{P}}})$, is obtained from $\Pi(G_{\delta})$ by switching $\mathcal{P}$ with the procedure described in \eqref{eq:switch}.

Next, we consider the pairing in the new graph $G_{0,\overline{\mathcal{P}}}$. 

In brief, some pairings remain unchanged, and some pairings must be modified depending on whether they are paired with edges in $\mathcal{P}$. 

\begin{itemize}
\item[(\text{I})] We start with an easy case. Specifically, suppose that $\mathcal{P}$ is a $x\rightarrow y$ path that does not contain any loop and is of the form 
\begin{align}\label{eq:noLoop}
\begin{split}
x&=a_{0}\rightarrow a_{1}\rightarrow a_{2}\rightarrow \cdots \rightarrow a_{n}=y,\\
&\text{and}\ a_{k}\not=a_{l}\ \text{if}\ k\not=l.
\end{split}
\end{align}

Fix a site $v\in \mathbb{Z}^3$, the pairing of an edge $e_{v\rightarrow w}$ (or $e_{w\rightarrow v}$) at the site $v$ will stay the same in the following two possibilities:
\begin{itemize}
\item the edge is not paired with any edge of $\mathcal{P}$,
\item the edge $e_{v\rightarrow w}$ (or $e_{w\rightarrow v}$) is part of $\mathcal{P}$ and is already paired to another edge in $\mathcal{P}$ at $v$. 
\end{itemize}

Otherwise, $v=a_k$ for some $k=1,2,\cdots,n-1$ there are two possible pairings of $e_{a_k\rightarrow w}$ (or $e_{w\rightarrow a_k}$) at the site $a_k$, and we handle them differently. In what follows we only consider $e_{a_k\rightarrow w}$ at the site $a_k$. That for $e_{w\rightarrow a_k}$ is almost identical, and hence is omitted.
\begin{itemize}
\item  The edge $e_{a_{k}\rightarrow w}$ is part of $\mathcal{P}$, thus $w=a_{k+1}$ by \eqref{eq:noLoop}. At $a_k$ it is paired with an edge $e_{b_{k-1}\rightarrow a_k}\not\in \mathcal{P}$. And the edge $e_{a_{k-1}\rightarrow a_k}\in \mathcal{P}$ is paired with $ e_{a_k\rightarrow c_{k+1}}\not\in \mathcal{P}$. 

Then in the new graph $G_{0,\overline{\mathcal{P}}}$ where we reverse the path $\mathcal{P}$, at $a_k$, $e_{a_{k}\leftarrow a_{k+1}}$ is paired with $e_{a_k\rightarrow c_{k+1}}$; and $e_{a_{k-1}\leftarrow a_k}$ is paired with $e_{a_k\leftarrow b_{k-1}}$. 

\item The edge $e_{a_{k}\rightarrow w}$ is not part of $\mathcal{P}$, and at $a_k$ it is paired with $e_{a_{k-1}\rightarrow a_k}\in \mathcal{P},$ and the edge $e_{a_k\rightarrow a_{k+1}}\in \mathcal{P}$ is paired with an edge $e_{c\rightarrow a_k}$. 

Then in the new graph $G_{0,\overline{\mathcal{P}}}$ where we reverse the path $\mathcal{P}$, at $a_k,$ $e_{a_{k}\rightarrow w}$ is paired with $e_{a_k\leftarrow a_{k+1}}$, and $e_{c\rightarrow a_k}$ is paired with $e_{a_{k-1}\leftarrow a_k}$.

\end{itemize}
To illustrate the procedure, we use the Figures \ref{image2} and \ref{image3}. Both are paired graphs. In Figure \ref{image2}, the paired path and loop are $x\rightarrow a1\rightarrow a2\rightarrow y$ and $b1\rightarrow a1\rightarrow b2\rightarrow b3\rightarrow a2\rightarrow b4\rightarrow b1$. And the chosen (unpaired) path for surgical switching, $\mathcal{P}$, is $$\mathcal{P}=x\rightarrow a1\rightarrow b2\rightarrow b3\rightarrow a2\rightarrow y.$$ Figure \ref{image3} is obtained after the surgical switching, the paired path and loop are $y\rightarrow a2\rightarrow b4\rightarrow b1\rightarrow a1\rightarrow x$ and $a1\rightarrow a2\rightarrow b3\rightarrow b2\rightarrow a1.$

\item[(\text{II})] For the general case, $\mathcal{P}$ can be decomposed, disjointly, into 
    \begin{align}\label{eq:decomP}
    \mathcal{P}=\mathcal{P}_1\cup \mathcal{P}_2\cup \cdots \mathcal{P}_{m}
    \end{align}
    and each of $\mathcal{P}_k$ is a self-avoiding path or loop, then we make the surgical switching for each one of them similarly.
    \end{itemize}

\label{LM:ReSurg}
     If $G_{\delta,N}(x\rightarrow y)$ and $F_{0,N}(y\rightarrow x)$ are two partially paired graphs in the region $|z|\leq N$, and $\mathcal{P}=\mathcal{P}(x\rightarrow y)\subset \Pi(G_{\delta,N}(x\rightarrow y))$ is a unpaired graph contained in the region $|z|<N$, such that $$G_{\delta,N}(x\rightarrow y)\xrightarrow[\text{surgical}]{\mathcal{P}} F_{0,N}(y\rightarrow x),$$ then
\begin{align}\label{eq:ReSurg}
    D_{\widehat{G_{\delta,N}}(x\rightarrow y)}=D_{\widehat{F_{0,N}}(y\rightarrow x)}.
\end{align}

To simplify notations we use the same conventions as in \eqref{eq:conventionDelta0}.

We start from \eqref{eq:surgicalLoop1} and \eqref{eq:uniform}, which imply that 
\begin{align}\label{eq:iden1}
\sum_{\Pi(V_{\delta,N})=\Pi(G_{\delta,N})} D_{\widehat{V_{\delta,N}}  }
    =\sum_{\Pi(K_{0,N})=\Pi(F_{0,N})}D_{\widehat{K_{0,N}} }.
\end{align}

Our strategy is to show that, (1) on both sides of \eqref{eq:iden1}, the summations are taken over terms of equal weights; (2) the number of elements in the two summations are equal. Thus, every term involved is of equal weight as desired.

For the left hand side, the rule set in \eqref{eq:count} implies that $D_{\widehat{V_{\delta,N}} }=D_{\widehat{G_{\delta,N}} }$ in \eqref{eq:count}. Thus, 
\begin{align}\label{eq:iden2}
    \begin{split}
    &\sum_{\Pi(V_{\delta,N})=\Pi(G_{\delta,N})} D_{\widehat{V_{\delta,N}} }
    =\Upsilon_{G_{\delta,N} }\ 
    D_{\widehat{G_{\delta,N}} },
    \end{split}
\end{align} where $\Upsilon_{G_{\delta,N} }$ is used to count the number of elements in the summation:
\begin{align*}
    \Upsilon_{G_{\delta,N} }:=&\Big|\Big\{ \widehat{V_{\delta,N}}  \ \Big| \  \Pi(V_{\delta,N} )=\Pi(G_{\delta,N} )  \Big\} \Big|.
\end{align*}




Similarly, the right-hand side takes a new form
\begin{align}\label{eq:iden3}
\begin{split}
 \sum_{\Pi(K_{0,N})=\Pi(F_{0,N})}D_{\widehat{K_{0,N}} } 
 = \Upsilon_{F_{0,N} }  D_{\widehat{F_{0,N}} } 
\end{split}
\end{align} with 
\begin{align*}
    \Upsilon_{F_{0,N} }:=&\Big|\Big\{ \widehat{K_{0,N}} \ \Big| \  \Pi(K_{0,N} )=\Pi(F_{0,N} )  \Big\} \Big|.
\end{align*}

The three identities \eqref{eq:iden1}-\eqref{eq:iden3} imply that
\begin{align}\label{eq:equalNo}
\begin{split}
     \Upsilon_{G_{\delta,N} } D_{\widehat{G_{\delta,N}} }
   = \Upsilon_{F_{0,N} } D_{\widehat{F_{0,N}}  }.
\end{split}    
\end{align}  

Now we claim that
\begin{align}\label{eq:upsilon}
\Upsilon_{G_{\delta,N} }=\Upsilon_{F_{0,N} }.
\end{align} If this holds, then it implies the desired identity $$D_{\widehat{G_{\delta,N}} }=D_{\widehat{F_{0,N}}  }.$$ 

To prove \eqref{eq:upsilon}, we observe that for the $\mathcal{P}$ provided in the lemma, the surgical transformation $\xrightarrow[\text{surgical}]{\mathcal{P}}$, defined in \eqref{def:surgicalTran}, is a bijection between the sets $\Big\{ \widehat{V_{\delta,N}}  \ \Big| \  \Pi(V_{\delta,N} )=\Pi(G_{\delta,N} )  \Big\}$ and $\Big\{ \widehat{K_{0,N}}  \ \Big| \  \Pi(K_{0,N}  )=\Pi(F_{0,N} )  \Big\}$. Therefore, these two finite sets have the same number of elements, and hence \eqref{eq:upsilon} holds.

The proof is complete.
